    "title": "談判的鬼才",
    "theme": "契約",
    "story": "* **談判與簽約情境**：\n  * 「最近我們公司做了與大企業合併的 **proposal**。」\n  * 「是喔。那麼對 **alliance** 的 **stipulation** 與 **terms** 的 **compromise** 達成了嗎？」\n  * 「不，在 **negotiation** 中無法達成 **agreement**，結果變 **deadlock** 了。」\n  * 「我聽說您是最棒的 **negotiator** 所以才來找您，下次談判請幫我們進行指導。」\n  * （雙方內心想法：「想睡吧～想睡吧～簽名吧～簽名吧～」）\n  * 「我知道了，請相信我吧！」（全朝往好的方向解讀……）\n\n---",
